reenPower', 'Scene', 'ForkScene', 'ForkSmokeScene', 'KeyLights', 'ForkSmokeKeyLights', 'Explained', 'ForkSmokeExplained', 'SchoolGmail', 'ForkSmokeSchoolGmail', 'SchoolTriage', 'ForkSmokeSchoolTriage', 'SchoolMailTool', 'ForkSmokeSchoolMailTool', 'SchoolSendQueue', 'ForkSchoolSendQueue', 'ForkSmokeSchoolSendQueue', 'TerminalGuard', 'GameSoundLines', 'ForkCallName', 'ForkHeldLines', 'ForkSmokeHeldLines', 'JobMarks', 'JobBadges', 'ForkJobBadges', 'ForkSmokeJobBadges','ForkDigestReader', 'ForkSmokeDigestReader', 'BrowserRecall', 'ForkSmokeBrowserRecall', 'ForkSmokeClaudeCli') | ForEach-Object { Join-Path $root ('app\' + $_ + '.cs') }
